void Server::prepare_scout(Peer&peer){
 auto*p=core_->find(peer.id);if(!p||p->vehicle>=0)return;
 auto*tech=core_->find(-1);if(!tech){cqauthority::ClassState classes;classes.role=classes.next=cqauthority::Role::TECHNICIAN;auto h=add_player(-1,0,classes,false);tech=core_->resolve(h);}if(!tech||tech->vehicle>=0)return;
 V at=p->spawn_position;at.y=world_->ground_height(at.x,at.z)+.03;
 core_->clear_supply(p->handle);p->classes.next=cqauthority::Role::SCOUT;p->classes.utility_t2[1]=false;p->classes.primary_t2[1]=false;p->classes.primary_t3[1]=false;p->classes.secondary_t2[1]=false;
 p->dead=true;auto h=core_->respawn(p->handle,at);p=core_->resolve(h);if(!p)return;
 p->bot=false;p->staging=false;p->team=0;p->squad=0;p->hp=100;p->armor=0;p->invulnerable=0;p->yaw=0;p->cooldown=0;world_->teleport(h,at);peer.team=0;
 tech=core_->find(-1);tech->classes.next=cqauthority::Role::TECHNICIAN;tech->classes.primary_t2[3]=false;tech->classes.primary_t3[3]=false;tech->classes.utility_t2[3]=false;
 V behind=at+V{0,0,100};behind.y=world_->ground_height(behind.x,behind.z)+.03;
 tech->dead=true;auto ally=core_->respawn(tech->handle,behind);tech=core_->resolve(ally);if(!tech)return;
 tech->bot=false;tech->staging=false;tech->team=0;tech->squad=0;tech->hp=100;tech->armor=50;tech->invulnerable=0;tech->yaw=0;tech->velocity={};tech->input.blocked=true;world_->teleport(ally,behind);
 roster();log_.write("scout_fixture_ready",{{"scout",peer.id},{"technician",-1},{"position",json(at)},{"technician_position",json(behind)}});
}
void Server::vote_state(){Json view=Json::object();if(!ballot_.empty()){int yes=0,no=0;Json responses=Json::object();std::vector<int64_t>voted;for(auto row:ballot_){row.second?++yes:++no;voted.push_back(row.first);responses[std::to_string(row.first)]=row.second;}view={{"title","RESTART MATCH"},{"yes",yes},{"no",no},{"needed",electorate_.size()/2+1},{"seconds",std::max(0,int(std::ceil(vote_until_-now_)))},{"voted",voted},{"responses",responses},{"eligible",electorate_}};}broadcast(Type::CONTROL,{{"vote",view},{"votes_enabled",config_.enabled("sv_votes")}});}
void Server::evaluate_vote(){if(ballot_.empty())return;size_t yes=0,no=0;for(auto row:ballot_)row.second?++yes:++no;size_t needed=electorate_.size()/2+1;if(yes>=needed){core_->request_restart();ballot_.clear();electorate_.clear();vote_state();}else if(no>electorate_.size()-needed||now_>=vote_until_||core_->intermission()>0){ballot_.clear();electorate_.clear();vote_state();}}
void Server::population(){int humans=0,bots=0,teams[2]={};for(auto&p:core_->players())if(p.active){++teams[p.team];p.bot?++bots:++humans;}int desired=std::max(0,bot_fill_-humans);bool changed=false;for(auto&p:core_->players())if(p.active&&p.bot&&bots>desired){auto h=p.handle;--teams[p.team];core_->leave(h);world_->remove_actor(h.id);--bots;changed=true;}while(bots<desired){int team=teams[0]<=teams[1]?0:1;cqauthority::ClassState classes;classes.role=classes.next=cqauthority::Role((-next_bot_-1)%4);auto h=add_player(next_bot_--,team,classes,true);if(!h.id)break;++teams[team];++bots;changed=true;}if(changed)roster();}
