  for(size_t i=0;i<parts;++i){auto bytes=cqwire::packet(Type::FRAME);put64(bytes,last_frame_);put32(bytes,uint32_t(relevant.size()));put32(bytes,uint32_t(packed.size()));put32(bytes,uint32_t(i));put32(bytes,uint32_t(parts));put_double(bytes,0);put32(bytes,epoch_);size_t begin=i*cqwire::CHUNK,end=std::min(begin+cqwire::CHUNK,packed.size());bytes.insert(bytes.end(),packed.begin()+begin,packed.begin()+end);raw(p,bytes,1,false);}
