void Server::asset_jobs(){for(auto it=asset_jobs_.begin();it!=asset_jobs_.end();){if(it->future.wait_for(std::chrono::seconds(0))!=std::future_status::ready){++it;continue;}try{const auto&a=assets_.accept(it->future.get());for(auto&entry:peers_)if(entry.second.id==it->id&&entry.second.ready){auto&p=entry.second;p.profile.avatar=a.hash;if(auto*player=core_->find(p.id))player->reach=reach_profile(a.manifest);send(p,Type::ASSET_ACK,{{"hash",a.hash}});save(p);}broadcast(Type::AVATARS,{{"assets",assets_.catalog()}});roster();}catch(const std::exception&e){for(auto&entry:peers_)if(entry.second.id==it->id)reject(entry.second,e.what());}it=asset_jobs_.erase(it);}}
void Server::transfers(){size_t budget=4;for(auto&entry:peers_){auto&p=entry.second;if(p.upload_size&&now_-p.transfer_at>30){p.upload.clear();p.upload_size=0;}if(p.download.empty()||!budget||!enet_list_empty(&p.net->outgoingSendReliableCommands)||p.net->reliableDataInTransit>cqwire::CHUNK)continue;size_t end=std::min(p.download_offset+cqwire::CHUNK,p.download_size);auto bytes=cqwire::packet(Type::ASSET_CHUNK);put32(bytes,uint32_t(p.download_offset));size_t at=bytes.size();bytes.resize(at+end-p.download_offset);std::ifstream file(p.download,std::ios::binary);file.seekg(std::streamoff(p.download_offset));if(!file.read(reinterpret_cast<char*>(bytes.data()+at),std::streamsize(end-p.download_offset)))throw std::runtime_error("Avatar asset read failed");raw(p,bytes,3);p.download_offset=end;--budget;if(end==p.download_size){send(p,Type::ASSET_DONE,{{"hash",p.download_hash}},3);p.download.clear();}}}

void Server::benchmark_ready(){if(!options_.benchmark_players||bench_start_>=0)return;size_t ready=0;for(auto&entry:peers_)ready+=entry.second.ready;if(ready!=size_t(options_.benchmark_players))return;bench_start_=now_+options_.benchmark_warmup;double monotonic=seconds(Clock::now().time_since_epoch())+options_.benchmark_warmup;broadcast(Type::CONTROL,{{"benchmark_start_monotonic",monotonic},{"benchmark_seconds",options_.benchmark_seconds},{"benchmark_hz",core_->tick_rate()}});log_.write("benchmark_ready",{{"players",ready},{"warmup",options_.benchmark_warmup},{"seconds",options_.benchmark_seconds}});}
namespace {Json distribution(std::vector<double>v){if(v.empty())return Json::object();std::sort(v.begin(),v.end());double sum=0;for(double x:v)sum+=x;return {{"mean",sum/v.size()},{"p50",v[size_t(std::ceil(v.size()*.5))-1]},{"p95",v[size_t(std::ceil(v.size()*.95))-1]},{"p99",v[size_t(std::ceil(v.size()*.99))-1]},{"max",v.back()}};}}
Json Server::benchmark_report()const{Json result=status();std::vector<double>callback,interval,movement,combat,mode,encoding,world,publication;for(auto&s:bench_samples_){callback.push_back(s.callback);interval.push_back(s.interval);movement.push_back(s.movement);combat.push_back(s.combat);mode.push_back(s.mode);encoding.push_back(s.encoding);world.push_back(s.world);publication.push_back(s.publication);}double elapsed=bench_start_>=0?std::max(0.,now_-bench_start_):0;result["benchmark"]={{"players",options_.benchmark_players},{"peak_players",peak_players_},{"warmup_seconds",options_.benchmark_warmup},{"seconds",elapsed},{"ticks",bench_samples_.size()},{"hz",elapsed>0?bench_samples_.size()/elapsed:0},{"simulation_elapsed_seconds",core_->time()-bench_simulation_},{"callback_us",distribution(callback)},{"physics_interval_us",distribution(interval)},{"movement_us",distribution(movement)},{"combat_us",distribution(combat)},{"mode_us",distribution(mode)},{"encoding_us",distribution(encoding)},{"jolt_update_us",distribution(world)},{"publication_us",distribution(publication)},{"baseline",bench_baseline_},{"shots_by_class",bench_shots_},{"disconnected",disconnects_},{"stress",options_.benchmark_stress}};return result;}
void Server::tick(){population();evaluate_vote();bool measure=options_.benchmark_players&&bench_start_>=0&&now_>=bench_start_;if(measure&&bench_samples_.empty()){bench_tick_=core_->tick();bench_simulation_=core_->time();bench_baseline_=status();for(auto&p:core_->players())if(p.active)previous_shots_[p.handle.id]=p.shots;}
 auto begin=Clock::now();core_->advance(*world_);for(auto&entry:peers_)if(auto*p=core_->find(entry.second.id))entry.second.team=p->team;auto world_begin=Clock::now();world_->sync(core_->step_seconds());double world_us=seconds(Clock::now()-world_begin)*1e6;if(core_->round_epoch()!=epoch_){epoch_=core_->round_epoch();destruction_->reset(epoch_);broadcast(Type::DESTRUCTION,destruction_->state());}auto publication_begin=Clock::now();frame();double publication_us=seconds(Clock::now()-publication_begin)*1e6;double us=seconds(Clock::now()-begin)*1e6;max_tick_us_=std::max(max_tick_us_,us);total_tick_us_+=us;++ticks_;
 size_t players=0;for(auto&p:core_->players())if(p.active){++players;if(measure){auto&previous=previous_shots_[p.handle.id];if(p.shots>=previous)bench_shots_[size_t(p.classes.role)]+=p.shots-previous;previous=p.shots;}}peak_players_=std::max(peak_players_,players);
 if(measure){bench_samples_.push_back({us,bench_previous_>0?(now_-bench_previous_)*1e6:1e6/core_->tick_rate(),core_->timings.movement_us,core_->timings.combat_us,core_->timings.mode_us,core_->timings.snapshot_us,world_us,publication_us});bench_previous_=now_;}}

Json Server::status()const{int humans=0,bots=0;for(auto&p:core_->players())if(p.active){p.bot?++bots:++humans;}return {{"protocol",cqwire::PROTOCOL},{"runtime","standalone-cpp"},{"adaptive_tick",governor_.enabled},{"destruction",config_.enabled("sv_cq_destruction")},{"hostname",config_.text("sv_hostname")},{"players",humans},{"bots",bots},{"capacity",config_.capacity()},{"tick_hz",core_->tick_rate()},{"ticks",core_->tick()},{"simulation_seconds",core_->time()},{"wall_seconds",now_},{"tick_mean_us",ticks_?total_tick_us_/ticks_:0},{"tick_max_us",max_tick_us_},{"fallbacks",governor_.fallbacks},{"recoveries",governor_.recoveries},{"input_overflow",core_->counters.overflow},{"projectile_full",core_->counters.projectile_full},{"core_rejected",core_->counters.rejected},{"accepted_inputs",core_->counters.accepted},{"rejected",rejected_},{"shots",core_->counters.shots},{"damage",core_->counters.damage},{"frames",frames_},{"bytes_sent",bytes_sent_},{"snapshot_source_bytes",snapshot_full_bytes_},{"snapshot_relevant_bytes",snapshot_relevant_bytes_},{"snapshot_packed_bytes",snapshot_wire_bytes_},{"snapshot_deltas",snapshot_deltas_},{"snapshot_keyframes",snapshot_keyframes_},{"snapshot_budget_fallbacks",snapshot_budget_fallbacks_},{"snapshot_shared_population_frames",snapshot_shared_population_frames_},{"navigation_queries",world_->navigation.queries},{"navigation_failed",world_->navigation.failed},{"broken_cells",destruction_->broken_count()},{"collapsed_buildings",destruction_->collapsed_count()}};}
Json Server::command(const std::string&line){auto t=tokenize(line);if(!t.error.empty()||t.words.empty())return {{"error","Invalid command"}};auto&args=t.words;try{if(args[0]=="status"&&args.size()==1)return status();if(args[0]=="restart"&&args.size()==1){core_->request_restart();return {{"ok",true}};}if(args[0]=="bots"&&args.size()==2){size_t used=0;int n=std::stoi(args[1],&used);if(used!=args[1].size()||n<0||n>config_.capacity())throw std::runtime_error("Bot fill out of range");bot_fill_=n;return {{"ok",true},{"bots",n}};}if(args[0]=="kick"&&args.size()==2){int64_t id=std::stoll(args[1]);for(auto&entry:peers_)if(entry.second.id==id){reject(entry.second,"Removed by administrator");return {{"ok",true}};}return {{"error","Player not found"}};}if(args[0]=="say"&&args.size()>=2){auto text=line.substr(line.find(' ')+1);broadcast(Type::CHAT,{{"id",1},{"name","Server"},{"text",text},{"scope",0}});return {{"ok",true}};}if(args[0]=="loglevel"&&args.size()==2&&(args[1]=="off"||args[1]=="normal"||args[1]=="verbose")){log_.level(args[1]);return {{"ok",true}};}}catch(const std::exception&e){return {{"error",e.what()}};}return {{"error","Unsupported command"}};}
int Server::run(const std::atomic<bool>&stop){origin_=Clock::now();auto previous=origin_,next=origin_;log_.write("ready",status());while(!stop.load()){
  now_=seconds(Clock::now()-origin_);if(options_.duration>0&&now_>=options_.duration)break;if(options_.benchmark_players&&bench_start_>=0&&now_>=bench_start_+options_.benchmark_seconds)break;if(options_.benchmark_players&&bench_start_<0&&now_>180)throw std::runtime_error("Benchmark admission timeout");
  ENetEvent event;for(int count=0;count<1024&&enet_host_service(host_,&event,0)>0;++count){if(event.type==ENET_EVENT_TYPE_CONNECT){Peer p;p.net=event.peer;p.id=next_id_++;p.connected=p.last=now_;p.snapshot_ack.rate=40;p.snapshot_ack.capacity=8;p.input.rate=120;p.input.capacity=24;p.control.rate=12;p.voice.rate=55;peers_.emplace(event.peer,std::move(p));enet_peer_timeout(event.peer,16,5000,15000);}else if(event.type==ENET_EVENT_TYPE_RECEIVE){auto it=peers_.find(event.peer);if(it!=peers_.end())try{receive(it->second,event.packet->data,event.packet->dataLength);}catch(const std::exception&){reject(it->second,"Malformed packet");}enet_packet_destroy(event.packet);}else if(event.type==ENET_EVENT_TYPE_DISCONNECT){auto it=peers_.find(event.peer);if(it!=peers_.end()){disconnect(it->second);peers_.erase(it);roster();}}}
  for(auto&entry:peers_)if(!entry.second.ready&&now_-entry.second.connected>120)enet_peer_disconnect_now(entry.first,2);
  writer_->check();rcon_.poll(now_,[this](const std::string&line){return command(line);});auto current=Clock::now();if(options_.fast||current>=next){double elapsed=seconds(current-previous);previous=current;auto begin=current;tick();double us=seconds(Clock::now()-begin)*1e6;if(governor_.enabled){governor_.observe(us,std::max(elapsed,.000001));if(governor_.pending!=governor_.hz){int rate=governor_.pending;if(core_->transition_tick_rate(rate)&&governor_.commit(rate))log_.write("tick_transition",{{"hz",rate}});}}
   next+=std::chrono::duration_cast<Clock::duration>(std::chrono::duration<double>(core_->step_seconds()));if(Clock::now()-next>std::chrono::milliseconds(100))next=Clock::now();
  }asset_jobs();transfers();enet_host_flush(host_);if(now_>=next_profile_){for(auto&entry:peers_)save(entry.second);next_profile_=now_+10;}if(now_>=next_status_){log_.write("status",status());next_status_=now_+30;}if(!options_.fast)std::this_thread::sleep_for(std::chrono::milliseconds(1));
 }for(auto&entry:peers_)save(entry.second);writer_->flush();auto report=options_.benchmark_players?benchmark_report():status();log_.write("stopped",report);if(!options_.report.empty())atomic_json(options_.report,report);return 0;}
